item.stdout:
{"connection_id": "BC-6b4879293b2266887ec9", "ref": "WLC:Lam.4.4", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "Tongue of the infant clings from thirst", "note": "The commentary names a thirst-dried tongue as maʿṣūr; in Jerusalem's siege the infant's tongue clings to the palate for thirst, making the bodily image concrete in a scene of deprivation."}
{"connection_id": "BC-37850b1a5764f3f84dd7", "ref": "WLC:Lam.4.4", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "thirst-dried tongue in famine", "note": "The commentary names the tongue dried by thirst alongside a person unable to pass food; Lamentations depicts nursing infants whose tongues stick to their palates for thirst while children ask for bread and receive none."}
{"connection_id": "BC-2f3e8a719a7a64a1a4a4", "ref": "WLC:Mic.6.15", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "pressing without drinking", "note": "The commentary expects a useful extract after pressing; Micah's judgment reverses that expectation, as people tread grapes yet will not drink their wine because their labor yields them no enjoyment."}
{"connection_id": "BC-d705ec50acbf5a7bc705", "ref": "WLC:Num.5.24", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "Bitter water that brings a curse", "note": "The suspected woman is made to drink water of bitterness that brings a curse; this is a concrete counter-use of bitter liquid beside the commentary's bitter plant extract called medicine."}
{"connection_id": "BC-dadde0d755f2385785df", "ref": "WLC:Num.5.24", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "cursed bitter water drunk", "note": "The commentary's bitter liquid is a healing medicine; in the ordeal of jealousy the woman must drink water of bitterness that carries a curse, giving an ingested bitter fluid a punitive effect instead."}
{"connection_id": "BC-b3b1317ce9e2db833bf6", "ref": "WLC:Num.5.27", "target": "sec3", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "Bitter water brings bodily affliction", "note": "The ritual's consequence is that the water becomes bitter within the woman and brings a curse; bitterness here exposes and punishes rather than healing as in the commentary's medicinal sabr."}
{"connection_id": "BC-b7057e66d8a0e7bbd78b", "ref": "WLC:Prov.25.21", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "give water to a thirsty enemy", "note": "The commentary connects flowing essence with generosity and relief of thirst; Proverbs directs a person to feed a hungry enemy and give a thirsty enemy water, turning an ordinary drink into a costly good act."}
{"connection_id": "BC-aa693f5465aead83ce20", "ref": "WLC:Prov.27.17", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "Iron sharpens iron", "note": "The proverb says one person sharpens another as iron sharpens iron; this gives mutual exhortation a concrete image of improvement through another's words."}
{"connection_id": "BC-4fc1190d8058c77967a6", "ref": "WLC:Prov.27.17", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "one person sharpens another", "note": "The surah's reciprocal counsel follows the image of pressure yielding value; Proverbs says iron sharpens iron and one person sharpens another, a specific abrasive image for mutual improvement rather than solitary patience."}
{"connection_id": "BC-76d3a1401995cad2a6ac", "ref": "WLC:Prov.28.27", "target": "sec3", "tradition": "tevrat", "kind": "soydas", "basis": "خ س ر / Hebrew חסר, table sound correspondence", "note": "The commentary's loss stands opposite goodness given away; Proverbs says a person who gives to the poor will not lack, using חסר to make generosity a way through deficiency rather than a cause of it."}
{"connection_id": "BC-b8b152e3e196a6d31be9", "ref": "WLC:Prov.3.10", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "Vats filled with new wine", "note": "The next verse promises vats brimming with new wine; the commentary's juice as beneficial abundance finds a concrete biblical image of overflowing produce."}
{"connection_id": "BC-b34a63b45f8ac58cbb18", "ref": "WLC:Prov.3.9", "target": "sec3", "tradition": "tevrat", "kind": "motif", "basis": "Honoring God with wealth", "note": "The verse commands honoring YHWH with one's wealth and first produce; beside the commentary's claim that extracted juice figures good and generosity, it makes abundance an act of giving."}
