text(await tools.apply_patch("*** Begin Patch
*** Update File: enrichment/bible/work/s103/ehlikitap-images.sol.max.s103-20261009/sec3/verdicts.jsonl
@@
 {"connection_id":"BC-c2c25ec1531bed53f129","ref":"WLC:Isa.63.3","status":"rejected","reason":"This is a genuine wrath-press image, but Revelation 14:19-20 states the destructive blood-yield explicitly, while Isaiah 63:3 gives no separate feature for this short page.","paragraphs":[12],"evidence":["WLC:Isa.63.3"],"annotations":[]}
+{"connection_id":"BC-0c679156825d5b66093a","ref":"WLC:Isa.65.8","status":"rejected","reason":"The new wine is found in a cluster and spared for a blessing, but the verse does not squeeze grapes or store a bitter remedy.","paragraphs":[10],"evidence":["WLC:Isa.65.8"],"annotations":[]}
+{"connection_id":"BC-8ca2f8a94191c0741845","ref":"WLC:Jer.2.13","status":"rejected","reason":"Cracked cisterns fail to hold water, but Jeremiah tells no shared surah story; a counter-narrative label overstates the vessel resemblance.","paragraphs":[11],"evidence":["WLC:Jer.2.13"],"annotations":[]}
+{"connection_id":"BC-8abf73e5164e759c2dbb","ref":"WLC:Jer.2.13","status":"rejected","reason":"The failed cistern is an image of Judah's chosen false sources, not a bottle whose seal preserves a medicinal extract; 2 Corinthians 4:7 supplies held value.","paragraphs":[11],"evidence":["WLC:Jer.2.13"],"annotations":[]}
+{"connection_id":"BC-4c73f1b30e7b1a63d8fd","ref":"WLC:Jer.32.14","status":"rejected","reason":"A clay jar preserves land deeds, not liquid; the relation is only the generic function of a container protecting valuables.","paragraphs":[11],"evidence":["WLC:Jer.32.14"],"annotations":[]}
+{"connection_id":"BC-1cc1251928425cef9ec8","ref":"WLC:Jer.48.11","status":"rejected","reason":"Moab's wine kept on lees retains taste because it was not poured, a complacency image rather than pressure producing and storing a remedy.","paragraphs":[11],"evidence":["WLC:Jer.48.11"],"annotations":[]}
+{"connection_id":"BC-225766ac5330f089a2fa","ref":"WLC:Job.14.1","status":"rejected","reason":"Job's short, troubled human life is a general frailty statement; Psalm 8:5-6 supplies both the human cognate and a lack verb.","paragraphs":[11],"evidence":["WLC:Job.14.1"],"annotations":[]}
+{"connection_id":"BC-4787a629210afa5d6db0","ref":"WLC:Job.32.19","status":"rejected","reason":"Elihu's unspoken words swell like wine in skins, a venting metaphor; no extraction, healing content, or patience is claimed.","paragraphs":[11],"evidence":["WLC:Job.32.19"],"annotations":[]}
+{"connection_id":"BC-55843974c0ad60278448","ref":"WLC:Job.7.17","status":"rejected","reason":"Job's anguished 'what is mortal man' is a valid אנוש use, but Psalm 8 uses the same question and follows it immediately with חסר, the page's second root.","paragraphs":[11],"evidence":["WLC:Job.7.17"],"annotations":[]}
+{"connection_id":"BC-7d3a77a04b419eb0b272","ref":"WLC:Job.7.17","status":"rejected","reason":"The second Job proposal repeats the mortal-human question; Psalm 8:5-6 gives the tighter joined אנוש and diminution wording.","paragraphs":[11],"evidence":["WLC:Job.7.17"],"annotations":[]}
+{"connection_id":"BC-969f07260a49e5112b3b","ref":"WLC:Job.7.18","status":"rejected","reason":"God tests the human every moment, but אנוש is in 7:17, not this verse; this continuation has no separate cognate or pressed-essence point.","paragraphs":[11],"evidence":["WLC:Job.7.18"],"annotations":[]}
+{"connection_id":"BC-bbb11adbf6dcdef07475","ref":"WLC:Joel.1.14","status":"rejected","reason":"עצרה means a solemn assembly here, not grape squeezing; the gathered fast does not describe people advising one another in patience.","paragraphs":[10],"evidence":["WLC:Joel.1.14"],"annotations":[]}
